package org.example

val Char.isNewline: Boolean inline get() = when (this) {
    '\n', '\r', '\u000B', '\u000C', '\u0085', '\u2028', '\u2029' -> true
    else -> false
}

val String.newlines: Int get() {
    var idx = 0
    var count = 0

    while (idx < length) {
        val curr = get(idx)
        val next = getOrNull(idx + 1)

        idx += when {
            curr == '\r' && next == '\n' -> {
                count += 1

                2
            }

            curr.isNewline -> {
                count += 1

                1
            }

            else -> 1
        }
    }

    return count
}

internal val KordNode?.length: Int inline get() = this?.length ?: 0
internal val KordNode?.newlines: Int inline get() = this?.newlines ?: 0

interface Kord {
